```python
class Solution:
    def totalNQueens(self, n: int) -> int:
        def is_eligible(i, path):
            return all(i != x for x in path)

        res = 0
        path = [0] * n
        for i in range(n):
            if is_eligible(i, path):
                path[i] = 1
                res += dfs(path, n)
                path[i] = 0

        return res

    def dfs(path, n):
        if all(x == 1 for x in path):
            return 1
        res = 0
        for i in range(n):
            if not path[i]:
                path[i] = 1
                res += dfs(path, n)
                path[i] = 0
